/bin/bash -lc "set -eu
python3 - <<'PY'
import hashlib, json, os, stat, subprocess
from pathlib import Path

root = Path.cwd()
work = root / '.t03-review.CM2qpy'
repo = work / 'repo'
materials = [root / 'SKILL.md', *[p for name in ('17','23','24','agents','assets','references') for p in (root / name).rglob('*') if p.is_file()]]
def snapshot(paths):
    return {p: (stat.S_IMODE(p.stat().st_mode), hashlib.sha256(p.read_bytes()).hexdigest()) for p in paths}
before = snapshot(materials)
def run(args, **kw):
    return subprocess.run(args, check=True, capture_output=True, text=True, **kw).stdout
def invoke(dir_, code, *args):
    return json.loads(run(['node','--input-type=module','-e',\"\"\"
import { loadCatalog, setPinned, saveCatalog, pinnedTitles } from './src/catalog.mjs';
import assert from 'node:assert/strict';
const [path, value] = process.argv.slice(1);
\"\"\" + code,*args], cwd=dir_))
def cards(first, second=True):
    return [{'id':'a','title':'Alpha', 'pinned':first}, {'id':'b','title':'Beta', 'pinned':second}, {'id':'c','title':'Gamma','pinned':False}]
def fields_without_flags(rows):
    return [{k:v for k,v in row.items() if k "'!= '"'pinned'} for row in rows]

for revision in ('R1','R2'):
    tree = work / revision
    run(['git','-C',str(repo),'worktree','add','--detach',str(tree),revision])
    original_paths = [p for p in tree.rglob('*') if p.is_file()]
    tree_before = snapshot(original_paths)
    head = run(['git','rev-parse','HEAD'],cwd=tree).strip()
    assert head == run(['git','-C',str(repo),'rev-parse',revision]).strip()
    print(revision, head)
    test = run(['npm','test'],cwd=tree,env=dict(os.environ,npm_config_cache=str(work/'npm-cache')))
    print('\\n'.join(line for line in test.splitlines() if '✔' in line or 'pass 2' in line or 'fail 0' in line))
    for scenario,initial,desired in [('pin',cards(False),True),('unpin',cards(True),False),('legacy pin',[{'id':'a','title':'Alpha'},*cards(False)[1:]],True)]:
        path = work / (revision+'-'+scenario.replace(' ','-')+'.json')
        path.write_text(json.dumps(initial))
        expected = cards(desired)
        write = invoke(tree,\"\"\"
const previous = loadCatalog(path);
const changed = setPinned(previous, 'a', value === 'true');
saveCatalog(path, changed);
console.log(JSON.stringify({ previous, changed, pins: pinnedTitles(changed) }));
\"\"\",str(path),str(desired).lower())
        raw = json.loads(path.read_text())
        fresh = invoke(tree,\"\"\"
const cards = loadCatalog(path);
console.log(JSON.stringify({ cards, pins: pinnedTitles(cards) }));
\"\"\",str(path))
        print(scenario, json.dumps({'before':write['previous'], 'changed':write['changed'], 'raw':raw, 'fresh':fresh},ensure_ascii=False))
        assert write['previous'] == (cards(True) if scenario=='unpin' else cards(False))
        assert write['changed'] == expected
        assert fields_without_flags(raw) == fields_without_flags(initial)
        assert fields_without_flags(fresh['cards']) == fields_without_flags(initial)
        assert raw == (expected if revision=='R1' else fields_without_flags(expected))
        assert fresh['cards'] == (expected if revision=='R1' else cards(False,False))
    missing = work / (revision+'-unknown.json')
    missing.write_text(json.dumps(cards(False)))
    before_error = missing.read_bytes()
    error = invoke(tree,\"\"\"
const cards = loadCatalog(path);
let message;
try {
  saveCatalog(path, setPinned(cards, 'missing', true));
} catch (error) {
  message = error.message;
}
assert.equal(message, 'Unknown card: missing');
console.log(JSON.stringify(message));
\"\"\",str(missing))
    assert missing.read_bytes() == before_error
    print('unknown',error,'same bytes',True)
    assert head == run(['git','rev-parse','HEAD'],cwd=tree).strip()
    assert run(['git','status','--porcelain'],cwd=tree) == ''
    assert tree_before == snapshot(original_paths)
assert before == snapshot(materials)
print('Worktree HEADs, status and delivered file hashes and modes verified')
PY"

